const testClick = await browserjs(tabId, () => {
  const board = document.querySelector('cg-board');
  if (!board) return "no board";
  const rect = board.getBoundingClientRect();
  const sqSize = rect.width / 8;

  // function to simulate a mouse/pointer click on square (file 0-7: a-h, rank 0-7: 1-8 from bottom)
  // Or rank 0-7 from top: rank 8 is top (y = 0..sqSize), rank 1 is bottom (y = 7*sqSize..8*sqSize)
  // Let's check where the rook is!
  const whiteRook = Array.from(document.querySelectorAll('piece.white.rook')).find(p => p.style.transform && !p.classList.contains('ghost'));
  const star = document.querySelector('star') || document.querySelector('.star') || document.querySelector('piece.black.pawn');

  return {
    rect,
    sqSize,
    whiteRookPos: whiteRook ? whiteRook.style.transform : null,
    starPos: star ? star.style.transform : null
  };
});
