const moveResult = await browserjs(tabId, () => {
  const board = document.querySelector('cg-board');
  const rect = board.getBoundingClientRect();

  function clickAt(x, y) {
    const opts = { bubbles: true, cancelable: true, clientX: rect.left + x, clientY: rect.top + y, button: 0 };
    board.dispatchEvent(new PointerEvent('pointerdown', opts));
    board.dispatchEvent(new MouseEvent('mousedown', opts));
    board.dispatchEvent(new PointerEvent('pointerup', opts));
    board.dispatchEvent(new MouseEvent('mouseup', opts));
    board.dispatchEvent(new MouseEvent('click', opts));
  }

  // Click rook at 288 + 36 = 324, 432 + 36 = 468
  clickAt(324, 468);
  // Then click star at 288 + 36 = 324, 72 + 36 = 108
  setTimeout(() => {
    clickAt(324, 108);
  }, 100);

  return "dispatched";
});

