const tabId = 918806481;

async function dragBoard(fromX, fromY, toX, toY) {
  const boardGeom = await browserjs(tabId, () => {
    const b = document.querySelector('cg-board');
    const r = b.getBoundingClientRect();
    return { left: r.left, top: r.top, width: r.width, height: r.height };
  });
  const startX = Math.round(boardGeom.left + fromX + 36);
  const startY = Math.round(boardGeom.top + fromY + 36);
  const endX = Math.round(boardGeom.left + toX + 36);
  const endY = Math.round(boardGeom.top + toY + 36);
  await tool.mouse({ action: "drag", tabId, start_coordinate: [startX, startY], coordinate: [endX, endY] });
}

// Move 1: (216, 288) -> (0, 288)
await dragBoard(216, 288, 0, 288);
await new Promise(r => setTimeout(r, 400));

// Move 2: (0, 288) -> (432, 288)
await dragBoard(0, 288, 432, 288);
await new Promise(r => setTimeout(r, 400));

// Move 3: (432, 288) -> (432, 360)
await dragBoard(432, 288, 432, 360);
await new Promise(r => setTimeout(r, 800));

const check = await browserjs(tabId, () => {
  return {
    url: window.location.href,
    body: document.body.innerText.slice(0, 250)
  };
});
console.log(check);

