const details = await browserjs(tabId, async () => {
  const resp = await fetch("https://lichess1.org/assets/compiled/learn.KTLLD7A7.js");
  const text = await resp.text();
  // search for stage names
  const match = text.match(/stages:\s*\[(.*?)\]/);
  // or search for stage list
  const stages = [];
  const re = /{\s*id:\s*"([^"]+)",\s*name:\s*"([^"]+)"/g;
  let m;
  while ((m = re.exec(text)) !== null) {
    stages.push({ id: m[1], name: m[2] });
  }
  return { stages, sample: text.slice(0, 1000) };
});
