const searchResult = await browserjs(tabId, async () => {
  const resp = await fetch("https://lichess1.org/assets/compiled/learn.KTLLD7A7.js");
  const text = await resp.text();
  const index = text.indexOf("stages");
  const matches = [];
  let pos = 0;
  while ((pos = text.indexOf("stages", pos)) !== -1) {
    matches.push(text.slice(Math.max(0, pos - 50), Math.min(text.length, pos + 150)));
    pos += 6;
    if (matches.length >= 10) break;
  }
  return matches;
});
