const tabId = 918806481;
const testSave = await browserjs(tabId, async () => {
  const mod = await import("https://lichess1.org/assets/compiled/lib.TQBWC2JZ.js");
  // Let's get the foundational stages:
  // rook, bishop, queen, king, knight, pawn, capture, protection, combat, check1, outOfCheck, checkmate1, setup
  const foundationalKeys = [
    "rook", "bishop", "queen", "king", "knight", "pawn", // legal moves
    "capture", "protection", "combat",                    // basic tactics
    "check1", "outOfCheck", "checkmate1",                 // check and checkmate
    "setup"                                               // simple game play / board setup
  ];

  const progress = JSON.parse(localStorage.getItem("learn.progress") || '{"stages":{}}');
  for (const key of foundationalKeys) {
    const stage = mod.l.find(s => s.key === key);
    if (stage) {
      // each level score is e.g. 600
      progress.stages[key] = {
        scores: stage.levels.map(() => 600)
      };
    }
  }
  localStorage.setItem("learn.progress", JSON.stringify(progress));
  return { progressKeys: Object.keys(progress.stages) };
});
