const qDef = await browserjs(tabId, async () => {
  const resp = await fetch("https://lichess1.org/assets/compiled/learn.KTLLD7A7.js");
  const text = await resp.text();
  // Find "function q(" or "var q=" or "let q="
  const matches = text.match(/(?:function\s+q\b|var\s+q\s*=|let\s+q\s*=|const\s+q\s*=)[^;{]+[{=][^;]+;/g) || [];
  // Or let's search for "q="
  const qIndices = [];
  let pos = 0;
  while ((pos = text.indexOf("q=", pos)) !== -1) {
    qIndices.push(text.slice(Math.max(0, pos - 40), Math.min(text.length, pos + 100)));
    pos += 2;
    if (qIndices.length >= 10) break;
  }
  return { matches, qIndices };
});
