const tabId = 918806481;
const scores = await browserjs(tabId, async () => {
  const mod = await import("https://lichess1.org/assets/compiled/lib.TQBWC2JZ.js");
  const resp = await fetch("https://lichess1.org/assets/compiled/learn.KTLLD7A7.js");
  const text = await resp.text();

  // Find ee definition
  const eeIdx = text.indexOf("ee=");
  const eeStr = text.slice(eeIdx, eeIdx + 50);

  // We can also evaluate tt directly from the page
  // me = 50, ue = 50, ee[1] = 500
  // tt = t => (X(t.apples).length * 50) + (t.pointsForCapture ? (t.captures||0)*50 : 0) + 500
  function getApplesCount(apples) {
    if (!apples) return 0;
    if (typeof apples === 'string') return apples.trim().split(/\s+/).filter(Boolean).length;
    if (Array.isArray(apples)) return apples.length;
    return 0;
  }

  function getLvlScore(lvl) {
    const applesCount = getApplesCount(lvl.apples);
    const capCount = lvl.pointsForCapture ? (lvl.captures || 0) : 0;
    return applesCount * 50 + capCount * 50 + 500;
  }

  const stageScores = {};
  for (const [key, stage] of Object.entries(mod.n)) {
    stageScores[key] = stage.levels.map(lvl => getLvlScore(lvl));
  }
  return { eeStr, stageScores };
});
console.log(scores.eeStr);
console.log(scores.stageScores);

