const tabId = 918806490;
const startRes = await browserjs(tabId, () => {
  const container = document.querySelector('.dialog-content.game-setup');
  // Click Strength 1 label
  const strength1Label = Array.from(container.querySelectorAll('label')).find(l => l.innerText.trim() === '1');
  if (strength1Label) strength1Label.click();

  // Click Side White
  const whiteLabel = Array.from(container.querySelectorAll('label')).find(l => l.innerText.trim() === 'White');
  if (whiteLabel) whiteLabel.click();

  // Click submit button
  const submitBtn = container.querySelector('.lobby__start__button--ai') || Array.from(container.querySelectorAll('button')).find(b => b.innerText.includes('Play against computer'));
  if (submitBtn) {
    submitBtn.click();
