    cls: p.className,
    transform: p.style.transform
  })).filter(p => !p.cls.includes('ghost'));
  return {
    title: document.title,
    count: pieces.length,
    blackPieces: pieces.filter(p => p.cls.includes('black'))
  };
});
console.log(check);

