const tabId = 918806490;

async function playBlackMove(fromCol, fromRow, toCol, toRow) {
  const geom = await browserjs(tabId, () => {
    const b = document.querySelector('cg-board');
    const r = b.getBoundingClientRect();
    return { left: r.left, top: r.top, sq: r.width / 8 };
  });

  const pFrom = {
    x: Math.round(geom.left + (fromCol + 0.5) * geom.sq),
    y: Math.round(geom.top + (fromRow + 0.5) * geom.sq)
  };
  const pTo = {
    x: Math.round(geom.left + (toCol + 0.5) * geom.sq),
    y: Math.round(geom.top + (toRow + 0.5) * geom.sq)
  };

  await tool.mouse({ action: "drag", tabId, start_coordinate: [pFrom.x, pFrom.y], coordinate: [pTo.x, pTo.y] });
}

// In black orientation:
// col 0=h, 1=g, 2=f, 3=e, 4=d, 5=c, 6=b, 7=a
// row 0=rank 1, 1=rank 2, 2=rank 3, 3=rank 4, 4=rank 5, 5=rank 6, 6=rank 7, 7=rank 8
// e7: col 3, row 6
// e5: col 3, row 4
await playBlackMove(3, 6, 3, 4);
await new Promise(r => setTimeout(r, 2000));

const check = await browserjs(tabId, () => {
  return {
    title: document.title,
    count: Array.from(document.querySelectorAll('piece')).filter(p => !p.className.includes('ghost')).length
  };
});
console.log(check);

