const tabId = 918806490;

async function playSquareMove(from, to) {
  const geom = await browserjs(tabId, () => {
    const b = document.querySelector('cg-board');
    const r = b.getBoundingClientRect();
    return { left: r.left, top: r.top, sq: r.width / 8 };
  });

  const files = 'abcdefgh';
  const getCoords = (sq) => {
    const f = files.indexOf(sq[0]);
    const r = parseInt(sq[1], 10);
    const col = f;
    const row = 8 - r;
    return {
      x: Math.round(geom.left + (col + 0.5) * geom.sq),
      y: Math.round(geom.top + (row + 0.5) * geom.sq)
    };
  };

  const pFrom = getCoords(from);
  const pTo = getCoords(to);

  await tool.mouse({ action: "drag", tabId, start_coordinate: [pFrom.x, pFrom.y], coordinate: [pTo.x, pTo.y] });
}

await playSquareMove('e2', 'e4');
await new Promise(r => setTimeout(r, 1500));

